"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// 🎬 ImmersiveStory — format "image first"
//
// Un fond d'écran fixe (plein viewport) qui cross-fade au fil du scroll,
// et des sections de texte qui défilent à l'avant-plan.
//
// Chaque <StorySection> déclare son image de fond: quand la section atteint
// le centre du viewport, l'arrière-plan transitionne vers cette image.
// Implémentation 100% native (scroll + getBoundingClientRect), zéro dépendance.
//
// Usage:
//   <ImmersiveStory>
//     <StorySection image="images/placeholders/x.jpg" align="left">
//       <p>…</p>
//     </StorySection>
//   </ImmersiveStory>
// ---------------------------------------------------------------------------

type BackgroundConfig = {
  /** Chemin de l'image (relatif à /public), ex: "images/placeholders/stromae_2014_a.jpg" */
  src: string;
  /** object-position desktop, ex: "center 20%" ou "70% center" (défaut: "50% 50%") */
  position?: string;
  /** object-position mobile — permet de recadrer l'image sur petit écran (défaut: position desktop) */
  positionMobile?: string;
};

/**
 * Voile d'angle facultatif posé sur l'image de fond, pour la lisibilité du texte
 * qui passe dessus (images claires). Il vit dans la couche fixe: il ne défile
 * pas, c'est le texte qui le traverse.
 */
export type StoryVeil = "none" | "left" | "right";

const VEIL_SIDES = ["left", "right"] as const;

/**
 * Ce qu'une section déclare au conteneur. L'image et le voile sont deux axes
 * distincts: deux sections peuvent partager une image et demander des voiles
 * différents (cf. content.tsx). Le voile reste donc hors de `BackgroundConfig`,
 * qui sert d'identité au montage des <img> et ne doit pas se dédoubler pour une
 * raison de voile — deux <img> du même fichier se cross-faderaient l'un dans
 * l'autre et creuseraient un trou de luminosité à mi-transition.
 */
type SectionConfig = {
  bg: BackgroundConfig;
  veil: StoryVeil;
  veilStr: number;
};

/** La force du voile pilote son opacité: hors de [0,1] elle ne veut rien dire. */
const clampStr = (v: number) => (Number.isFinite(v) ? Math.min(Math.max(v, 0), 1) : 1);

type RegisterFn = (el: HTMLElement, cfg: SectionConfig) => () => void;

const StoryContext = createContext<RegisterFn | null>(null);

const bgKey = (bg: BackgroundConfig) =>
  `${bg.src}|${bg.position ?? ""}|${bg.positionMobile ?? ""}`;

// ---------------------------------------------------------------------------
// Conteneur principal: gère le fond fixe + l'observation du scroll
// ---------------------------------------------------------------------------

interface ImmersiveStoryProps {
  children: ReactNode;
  className?: string;
  /** Opacité du voile global posé sur les images (lisibilité). 0 = aucun voile. */
  scrim?: "none" | "light" | "medium";
}

export function ImmersiveStory({ children, className = "", scrim = "light" }: ImmersiveStoryProps) {
  const [backgrounds, setBackgrounds] = useState<BackgroundConfig[]>([]);
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [activeVeil, setActiveVeil] = useState<StoryVeil>("none");
  const [activeVeilStr, setActiveVeilStr] = useState(1);
  const [mountedKeys, setMountedKeys] = useState<Set<string>>(() => new Set());
  const sectionsRef = useRef(new Map<HTMLElement, SectionConfig>());
  const backgroundsRef = useRef<BackgroundConfig[]>([]);
  const activeKeyRef = useRef<string | null>(null);

  // Active une section: son voile, puis son image (cross-fade + montage
  // progressif — image courante, précédente et suivante, la suivante étant
  // ainsi préchargée à l'avance).
  const activate = useCallback((cfg: SectionConfig) => {
    // Avant le court-circuit sur l'image: deux sections voisines peuvent
    // partager une image et ne différer que par leur voile — côté ou force.
    setActiveVeil(cfg.veil);
    setActiveVeilStr(cfg.veilStr);

    const key = bgKey(cfg.bg);
    if (activeKeyRef.current === key) return;
    activeKeyRef.current = key;
    setActiveKey(key);
    setMountedKeys((prev) => {
      const next = new Set(prev);
      next.add(key);
      const list = backgroundsRef.current;
      const idx = list.findIndex((b) => bgKey(b) === key);
      if (idx >= 0 && list[idx + 1]) next.add(bgKey(list[idx + 1]));
      if (idx > 0) next.add(bgKey(list[idx - 1]));
      return next.size === prev.size ? prev : next;
    });
  }, []);

  // Détection déterministe: à chaque scroll, on identifie LA section dont le
  // rectangle couvre la ligne horizontale médiane du viewport, et on active
  // son image. Les sections s'empilent sans espace dans le flux du document,
  // donc exactement une section couvre toujours cette ligne (sauf tout en
  // haut/bas de page, géré par le repli "plus proche"). Remplace l'ancien
  // IntersectionObserver à bande de 10%: avec plusieurs entrées simultanées
  // (scroll rapide, allers-retours), l'ordre de traitement des entries ne
  // garantissait pas de retenir la section réellement au centre — d'où des
  // désynchronisations occasionnelles texte / image observées en usage.
  const recomputeActive = useCallback(() => {
    if (typeof window === "undefined" || sectionsRef.current.size === 0) return;
    const centerY = window.innerHeight / 2;
    let hit: SectionConfig | null = null;
    let closest: SectionConfig | null = null;
    let closestDist = Infinity;

    for (const [el, cfg] of sectionsRef.current) {
      const rect = el.getBoundingClientRect();
      if (rect.top <= centerY && rect.bottom >= centerY) {
        hit = cfg;
        break;
      }
      const dist = centerY < rect.top ? rect.top - centerY : centerY - rect.bottom;
      if (dist < closestDist) {
        closestDist = dist;
        closest = cfg;
      }
    }

    const next = hit ?? closest;
    if (next) activate(next);
  }, [activate]);

  const register = useCallback<RegisterFn>((el, cfg) => {
    sectionsRef.current.set(el, cfg);

    // Liste ordonnée (ordre du document) des images uniques
    const key = bgKey(cfg.bg);
    if (!backgroundsRef.current.some((b) => bgKey(b) === key)) {
      backgroundsRef.current = [...backgroundsRef.current, cfg.bg];
      setBackgrounds(backgroundsRef.current);
    }

    // La première section enregistrée devient le fond initial
    if (activeKeyRef.current === null) {
      activate(cfg);
    }
    recomputeActive();

    return () => {
      sectionsRef.current.delete(el);
    };
  }, [activate, recomputeActive]);

  // Écoute unique scroll/resize, cadencée par requestAnimationFrame pour ne
  // recalculer qu'une fois par frame peu importe le nombre d'événements.
  useEffect(() => {
    if (typeof window === "undefined") return;
    let ticking = false;
    const onScrollOrResize = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        ticking = false;
        recomputeActive();
      });
    };
    window.addEventListener("scroll", onScrollOrResize, { passive: true });
    window.addEventListener("resize", onScrollOrResize);
    return () => {
      window.removeEventListener("scroll", onScrollOrResize);
      window.removeEventListener("resize", onScrollOrResize);
    };
  }, [recomputeActive]);

  // Le voile "quart de cercle" n'existe que pour l'ouverture: elle seule occupe
  // exactement un écran (jamais de défilement interne), ce qui lui permet de
  // rester ancrée au même coin sans jamais se désynchroniser du texte.
  const isHeroActive = backgrounds.length > 0 && activeKey === bgKey(backgrounds[0]);

  // Le scrim ambiant assombrissait aussi le haut du viewport — y compris sur
  // l'ouverture, où un premier passage n'avait retiré ce haut que hors hero.
  // Le haut d'une image ne doit jamais être terni, même légèrement: seul le
  // bas s'assombrit (lisibilité du texte), sur toutes les sections sans
  // exception.
  const scrimClass =
    scrim === "none"
      ? null
      : scrim === "medium"
      ? "bg-gradient-to-b from-transparent via-black/25 to-black/60"
      : "bg-gradient-to-b from-transparent via-black/10 to-black/50";

  return (
    <StoryContext.Provider value={register}>
      {/* ===== Arrière-plan fixe ===== */}
      {/* h-lvh (et non inset-0): sur mobile, le bord bas d'un élément fixed
          suit la hauteur dynamique du viewport (barres du navigateur qui se
          rétractent au scroll). Comme l'image est en object-cover contrainte
          par la hauteur, chaque variation re-zoomait l'image. Une hauteur
          figée au grand viewport (100lvh) rend le fond totalement immobile;
          barres visibles, son bas déborde simplement sous elles. */}
      <div className="fixed inset-x-0 top-0 z-0 h-lvh overflow-hidden bg-black" aria-hidden="true">
        {backgrounds.map((bg) => {
          const key = bgKey(bg);
          if (!mountedKeys.has(key)) return null;
          const isActive = key === activeKey;
          return (
            <img
              key={key}
              src={bg.src}
              alt=""
              draggable={false}
              decoding="async"
              className={`story-bg-img absolute inset-0 h-full w-full object-cover transition-opacity duration-[1000ms] ease-in-out ${
                isActive ? "opacity-100" : "opacity-0"
              }`}
              style={
                {
                  "--bg-pos": bg.position ?? "50% 50%",
                  "--bg-pos-m": bg.positionMobile ?? bg.position ?? "50% 50%",
                } as CSSProperties
              }
            />
          );
        })}
        {scrimClass && <div className={`absolute inset-0 ${scrimClass}`} />}

        {/* Voiles d'angle facultatifs (props `veil` / `veilStr` des StorySection).
            Les deux coins sont toujours montés et pilotés par l'opacité: le
            passage gauche→droite se fond alors de lui-même, sans cas particulier,
            et le retour à "none" n'est qu'une extinction.
            La force se branche sur ce même canal — une variation de dosage entre
            deux sections d'un même côté se fond donc comme le reste, sans code
            dédié. D'où l'opacité en style inline: elle est continue, là où les
            paliers de Tailwind ne le sont pas. */}
        {VEIL_SIDES.map((side) => (
          <div
            key={side}
            className={`story-veil story-veil--${side} absolute inset-0 transition-opacity duration-[1000ms] ease-in-out`}
            style={{ opacity: activeVeil === side ? activeVeilStr : 0 }}
          />
        ))}

        {/* Voile de l'ouverture: quart de cercle ancré bas-gauche, propre au hero. */}
        <div
          className={`story-hero-veil absolute inset-0 transition-opacity duration-[1000ms] ease-in-out ${
            isHeroActive ? "opacity-100" : "opacity-0"
          }`}
          aria-hidden="true"
        />
      </div>

      {/* ===== Contenu à l'avant-plan ===== */}
      <div className={`relative z-10 ${className}`}>{children}</div>
    </StoryContext.Provider>
  );
}

// ---------------------------------------------------------------------------
// StorySection — un "moment" de la story lié à une image de fond
// ---------------------------------------------------------------------------

interface StorySectionProps {
  /** Image de fond associée à cette section */
  image: string;
  /** object-position desktop, ex: "center 20%" / "70% center" */
  imagePosition?: string;
  /** object-position mobile — pour recadrer le sujet sur petit écran */
  imagePositionMobile?: string;
  /**
   * Voile noir circulaire posé dans un angle bas de l'image, pour rattraper la
   * lisibilité du texte sur une photo claire. Fixe (il ne défile pas avec la
   * section) et facultatif — à n'allumer que là où l'image l'exige.
   */
  veil?: StoryVeil;
  /**
   * Force du voile, de 0 (éteint) à 1 (pleine densité du dégradé). Se dose au
   * cas par cas: chaque photo a sa propre luminosité, et depuis que le scrim
   * ambiant est à "none" le voile est le seul assombrissement de la section.
   * Sans effet si `veil="none"`. Défaut: 1.
   */
  veilStr?: number;
  /** Position du bloc texte en desktop (mobile: toujours centré) */
  align?: "left" | "center" | "right";
  /** Hauteur de la section = espace de respiration entre les blocs */
  height?: "short" | "normal" | "tall";
  /** Largeur max du bloc texte */
  width?: "narrow" | "medium" | "wide";
  /** Alignement du texte à l'intérieur du bloc (défaut: left, ou center si align="center") */
  textAlign?: "left" | "center" | "right";
  /** Ancrage vertical du bloc texte dans la section */
  vAlign?: "center" | "bottom";
  id?: string;
  className?: string;
  contentClassName?: string;
  children: ReactNode;
}

const HEIGHT_CLASSES: Record<NonNullable<StorySectionProps["height"]>, string> = {
  short: "min-h-[100svh]",
  normal: "min-h-[150vh]",
  tall: "min-h-[200vh]",
};

const V_ALIGN_CLASSES: Record<NonNullable<StorySectionProps["vAlign"]>, string> = {
  center: "justify-center",
  bottom: "justify-end",
};

const WIDTH_CLASSES: Record<NonNullable<StorySectionProps["width"]>, string> = {
  narrow: "max-w-md",
  medium: "max-w-xl",
  wide: "max-w-2xl",
};

const ALIGN_CLASSES: Record<NonNullable<StorySectionProps["align"]>, string> = {
  left: "md:justify-start",
  center: "md:justify-center",
  right: "md:justify-end",
};

// Toujours à gauche en mobile (le jeu centre/droite n'a de sens qu'en desktop,
// où le bloc de texte partage l'espace avec la photo) — desktop reprend
// l'alignement résolu. Classes Tailwind littérales (pas de `text-${x}`
// interpolé): un template dynamique n'est jamais vu par le scanner de Tailwind
// et ne génère aucune règle CSS.
const TEXT_ALIGN_CLASSES: Record<NonNullable<StorySectionProps["textAlign"]>, string> = {
  left: "text-left md:text-left",
  center: "text-left md:text-center",
  right: "text-left md:text-right",
};

export function StorySection({
  image,
  imagePosition,
  imagePositionMobile,
  veil = "none",
  veilStr = 1,
  align = "center",
  height = "normal",
  width = "medium",
  textAlign,
  vAlign = "center",
  id,
  className = "",
  contentClassName = "",
  children,
}: StorySectionProps) {
  const register = useContext(StoryContext);
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!register || !ref.current) return;
    return register(ref.current, {
      bg: {
        src: image,
        position: imagePosition,
        positionMobile: imagePositionMobile,
      },
      veil,
      veilStr: clampStr(veilStr),
    });
  }, [register, image, imagePosition, imagePositionMobile, veil, veilStr]);

  const resolvedTextAlign = textAlign ?? (align === "center" ? "center" : "left");

  return (
    <section
      id={id}
      ref={ref}
      className={`relative flex flex-col px-5 py-24 md:px-[7%] ${V_ALIGN_CLASSES[vAlign]} ${HEIGHT_CLASSES[height]} ${className}`}
    >
      <div className={`relative flex w-full max-w-screen-2xl mx-auto justify-center ${ALIGN_CLASSES[align]}`}>
        <div
          className={`w-full text-white ${WIDTH_CLASSES[width]} story-text-shadow ${TEXT_ALIGN_CLASSES[resolvedTextAlign]} ${contentClassName}`}
        >
          {children}
        </div>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// Petits éléments d'habillage réutilisables
// ---------------------------------------------------------------------------

/**
 * Repère de chapitre («Chapitre 1», «Chapitre 2»…) — jamais un surtitre générique.
 * Le filet d'or qui le suit lie kicker et titre en un seul bloc "affiche", comme
 * au hero.
 */
export function StoryKicker({ children, className = "" }: { children: ReactNode; className?: string }) {
  return (
    <div className={`story-kicker-group ${className}`}>
      <p className="story-kicker">{children}</p>
      <span className="story-kicker__rule" aria-hidden="true" />
    </div>
  );
}

/** Intertitre de chapitre */
export function StoryHeading({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <h2 className={`story-heading ${className}`}>{children}</h2>;
}

/**
 * Repère de scroll. Vit dans le flux du bloc texte (et non en absolute au centre du
 * viewport), pour se poser au bout de la ligne de signature sans jamais la heurter.
 */
export function ScrollCue({ label = "Faites défiler" }: { label?: string }) {
  return (
    <span className="story-cue">
      <span>{label}</span>
      <svg
        className="story-cue__arrow"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.75"
        viewBox="0 0 24 24"
        aria-hidden="true"
      >
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 5v14M19 12l-7 7-7-7" />
      </svg>
    </span>
  );
}
